import { useEffect, useState } from "react";

export default function AdminOrders() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/orders/")
      .then(res => res.json())
      .then(setOrders);
  }, []);

  const updateStatus = (order_id, status) => {
    fetch(`http://127.0.0.1:8000/api/orders/${order_id}/status/`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ status })
    });

    setOrders(prev =>
      prev.map(o =>
        o.order_id === order_id ? { ...o, status } : o
      )
    );
  };

  return (
    <div>
      <h3>Admin Orders</h3>

      {orders.map(o => (
        <div key={o.order_id}>
          <h4>Order #{o.order_id}</h4>
          <p>User: {o.user}</p>
          <p>Total: ₹{o.total}</p>

          <select
            value={o.status}
            onChange={e => updateStatus(o.order_id, e.target.value)}
          >
            <option>Pending</option>
            <option>Ready</option>
            <option>Completed</option>
          </select>
        </div>
      ))}
    </div>
  );
}
